<?php require_once __DIR__.'/../config/config.php';require_admin();$allowed=['bookings','clients','client_galleries','portfolio_items','reviews','offers','social_posts','site_events','admin_activity'];if(isset($_GET['table'])){$table=(string)$_GET['table'];if(!in_array($table,$allowed,true)){http_response_code(400);exit('Invalid export table.');}$q=$pdo->query("SELECT * FROM `$table` LIMIT 10000");header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="acp-'.$table.'-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');$first=$q->fetch(PDO::FETCH_ASSOC);if($first){fputcsv($out,array_keys($first));fputcsv($out,array_values($first));while($row=$q->fetch(PDO::FETCH_ASSOC))fputcsv($out,array_values($row));}fclose($out);exit;}$pageTitle='Data export';$active='export';require __DIR__.'/_layout.php';?><section class="welcome-row"><div><p class="eyebrow">PORTABILITY</p><h1>Export studio <em>data.</em></h1><p class="muted">Download selected database tables as CSV. Export is restricted to authenticated administrators.</p></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>DATASET</th><th>FORMAT</th><th>ACTION</th></tr></thead><tbody><?php foreach($allowed as $t):?><tr><td><?=e(ucwords(str_replace('_',' ',$t)))?></td><td>CSV · up to 10,000 rows</td><td><a class="btn btn-small" href="export.php?table=<?=e($t)?>">Download CSV ↗</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>